const $=s=>document.querySelector(s);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=x=>x===null||x===undefined?'—':new Intl.NumberFormat('fr-CH').format(x);
const numeric=x=>x.trim()===''?null:Number(x);
let assetMap={},logos={},cardSprites={},materialsById=new Map();
const absolute=x=>assetMap[x]|| (x?.startsWith('client-images/')||x?.startsWith('client-logos/')||x?.startsWith('client-card-sprites/')?x:x?.startsWith('/naruto-blazing/')?'https://gachawiki.net'+x:x?.startsWith('https://gachawiki.net/')?x:'');
const safeUrl=x=>/^https:\/\//.test(x||'')?esc(x):'#';
let catalogue,profile,lb,state,byId,all,releasedIds,toastTimer,characterSearchIndexes=new Map(),importPromptText='',importFeedback=null;
let ui={page:'collection',scope:'owned',search:'',element:[],sort:'catalogue',filter:'all',collectionStars:[],f2pOnly:false,resourceSearch:'',onlyMissing:true,stockSearch:'',dialogId:null,tab:'fiche',form:null,visible:72,planElement:[],planStars:[],planF2pOnly:false,planScope:'all'};
const FILTER_VALUES={element:Object.keys(ELEMENTS),planElement:Object.keys(ELEMENTS),collectionStars:['1','2','3','4','5','6'],planStars:['1','2','3','4','5','6']};
function resourceInfo(key,map){
  const info=baseResourceInfo(key,map),[kind,element,stars]=key.split(':');
  if(key==='tokens'){info.name='Jetons';info.subtitle='Achats nécessaires aux paliers restants';}
  if(key==='ryo')info.group='Ryō';
  if(kind==='scroll'){
    const mission=catalogue.farming?.missions?.[element],ranks=(mission?.stages||[]).filter(s=>s.drops.some(d=>d.stars===Number(stars))).map(s=>`${s.rank} (${s.stamina} énergie)`);
    info.subtitle=`${mission?.title||'Parchemins'} · ${ranks.join(' / ')}`;
  }
  if(kind==='element'&&lb.elements?.[element])info.subtitle=lb.elements[element].trial+' · Trial Missions';
  if(kind==='special'&&catalogue.farming?.special?.[info.name]){const s=catalogue.farming?.special?.[info.name];info.subtitle=`${s.mission} · rang ${s.rank}`;}
  const [,id]=key.split(':');
  const entry=logos.resourcesByStockKey?.[key];info.image=typeof entry==='string'?entry:entry?.path;
  if(kind==='copies'){const n=map.get(id),p=state.characters[id],f=n?.forms.find(f=>f.client?.unitId===p?.unitId)||n?.forms.find(f=>f.stars===p?.stars)||n?.forms.at(-1);info.image=f?.clientIcon||n?.clientIcon;}
  if((kind==='special'||kind==='material')&&materialsById.has(Number(id))){const m=materialsById.get(Number(id));info.name=`${m.name} ${m.stars}★`;info.subtitle=m.title||'Matériau du client';const entry=logos.materialsByUnitId?.[id];info.image||=typeof entry==='string'?entry:entry?.path;}
  return info;
}
function logoImage(path,cls='item-logo',alt=''){const src=absolute(path);return src?`<img class="${cls}" src="${esc(src)}" alt="${esc(alt)}" loading="lazy">`:'';}
function resourceGraphic(info){return info.image?logoImage(info.image,'item-logo',''):`<span class="resource-symbol">${info.icon}</span>`;}
function abilityGraphic(a,filled=false){const entry=logos.abilitiesById?.[a.id],path=a.icon||(typeof entry==='string'?entry:entry?.path);return path?logoImage(path,`ability-logo ${filled?'filled':''}`,''):'<span class="ability-missing" title="Logo indisponible">?</span>';}
function materialGraphic(m){const entry=logos.materialsByUnitId?.[m.id||m.clientId];return logoImage(m.icon||(typeof entry==='string'?entry:entry?.path),'item-logo','');}

function notify(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3300);}
function persist(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));$('#save-status').textContent='Sauvegardé sur ce navigateur';$('#save-status').classList.remove('save-warning');}catch{$('#save-status').textContent='Sauvegarde locale indisponible';$('#save-status').classList.add('save-warning');notify('Utilise « Sauvegarder » pour conserver tes changements.');}updateNav();}
function routePage(page){return page==='inventory'?'plan':page;}
function focusStockSection(){const section=$('#resource-needs');if(section){section.scrollIntoView({block:'start'});section.focus({preventScroll:true});}}
function updateNav(){$('#nav-owned').textContent=Object.values(state.characters).filter(p=>p.owned).length;document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',routePage(b.dataset.nav)===ui.page));document.querySelectorAll('nav [data-nav]').forEach(b=>{if(routePage(b.dataset.nav)===ui.page)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});$('#breadcrumb').textContent=({collection:'Collection / Ma box',plan:'Progression / Plan & stocks',sources:'Collection / Sources & sauvegarde',guide:'Guide / Bien démarrer & missions'})[ui.page];}
function owned(){return all.filter(n=>state.characters[n.id].owned);}
function isPersonalAccount(){return state.accountMode==='personal';}
function accountName(){return state.username||'Ma box';}
function collectionHeading(){return isPersonalAccount()&&accountName()==='Ma box'?'Ma collection':'Collection '+accountName();}
function maxStarsFor(n){return planningCharacter(n)?.maxStars??null;}
function missingCharacters(){return catalogue.released.filter(n=>!state.characters[n.id].owned&&maxStarsFor(n)!==null);}
function futureCharacters(){return catalogue.upcoming.filter(n=>releaseDate(n)&&maxStarsFor(n)!==null).sort((a,b)=>a.serverReleased.localeCompare(b.serverReleased)||a.name.localeCompare(b.name));}
function canEditCharacter(n){const p=state.characters[n.id],personallyObserved=isPersonalAccount()&&p.owned&&n.forms.some(f=>f.client?.unitId===p.unitId);return (releasedIds.has(n.id)||personallyObserved)&&maxStarsFor(n)!==null;}
function canUseResourcePlan(n){const p=state.characters[n.id];return canPlanCharacter(n)&&(!p.owned||!Number.isSafeInteger(p.stars)||p.stars<=CURRENT_MAX_STARS);}
function progressForms(n){return isPersonalAccount()&&state.characters[n.id].owned?n.forms:planningCharacter(n)?.forms||[];}
function previewMaximumForm(n){return planningCharacter(n)?.forms.at(-1)||n.forms.at(-1);}
function releaseDate(n){const raw=n.serverReleased;if(!/^\d{4}-\d{2}-\d{2}$/.test(raw||''))return null;const [y,m,d]=raw.split('-');return `${d}/${m}/${y}`;}
function displayTitle(n){return n.titleFr||n.title;}
function obtainLabel(n){const entries=n.obtain||[],labels=[];if(entries.some(x=>x.type==='summon'&&/friend summon/i.test(x.name)))labels.push('Invocation amie · F2P');if(entries.some(x=>['summon','banner','summons'].includes(x.type)&&!/friend summon/i.test(x.name)))labels.push('Bannière');if(entries.some(x=>['event','mission','emergency','impact','story','trial','raid','gaiden','rookie'].includes(x.type)))labels.push('F2P · Événement');if(entries.some(x=>x.type==='granny-cat'))labels.push('Boutique');for(const entry of entries.filter(x=>x.type==='gift'))labels.push(entry.name||'Cadeau');return labels.join(' / ')||'Obtention non précisée';}
function planMatches(n){const p=state.characters[n.id],scope=ui.planScope;return (scope==='all'||scope==='owned'&&p.owned||scope==='missing'&&!p.owned&&releasedIds.has(n.id)||scope==='future'&&!p.owned&&n.upcoming)&&matchesSelection(n.element,ui.planElement)&&matchesSelection(maxStarsFor(n),ui.planStars)&&(!ui.planF2pOnly||isF2PCharacter(n));}
function resetPlanFilters(){ui.planScope='all';ui.planElement=[];ui.planStars=[];ui.planF2pOnly=false;}
function planToggleButton(n,p,extra=''){return `<button type="button" class="button compact plan-toggle ${extra}" data-toggle-plan="${n.id}" ${canUseResourcePlan(n)?'':'disabled'} aria-pressed="${p.planned}" aria-label="${p.planned?'Retirer du plan':'Ajouter au plan'} · ${esc(n.name+' — '+displayTitle(n))}">${p.planned?'✓ Dans mon plan · Retirer':'＋ Ajouter au plan'}</button>`;}
function forecastCopy(n){return `Prévision depuis la forme de base au niveau 1, sans pilules. ${n.upcoming?'Les recettes et plafonds du client pourront changer à la sortie.':'Le calcul sera remplacé par ta progression réelle quand tu l’ajouteras à ta box.'}`;}
function plan(){return aggregateResourcePlan(ui.page==='plan'?all.filter(planMatches):all,state);}
function elementLogo(e,cls='filter-element-logo'){const entry=Object.values(cardSprites.elementsById||{}).find(x=>x.element===e);return logoImage(entry?.small?.path||entry?.large?.path,cls,'');}
function rarityLogo(stars,cls='filter-rarity-logo'){const entry=cardSprites.rarityLabels?.[stars];return logoImage(entry?.sourcePath||entry?.path,cls,'');}
function elementBadge(e){return `<span class="element-badge" style="--element:${ELEMENTS[e].color}">${elementLogo(e,'badge-element-logo')}${ELEMENTS[e].short}</span>`;}
function selectionText(value,allowed,label,empty='Tous'){const selected=normalizeSelection(value,allowed);return selected.length?selected.map(label).join(' + '):empty;}
function elementFilters(value,scope){
  const selected=normalizeSelection(value,Object.keys(ELEMENTS));
  return `<div class="icon-filter-group" role="group" aria-label="Filtrer par éléments · plusieurs choix possibles"><button type="button" class="icon-filter all-filter ${selected.length?'':'active'}" data-${scope}="all" aria-pressed="${!selected.length}">Tous</button>${Object.entries(ELEMENTS).map(([element,info])=>`<button type="button" class="icon-filter ${selected.includes(element)?'active':''}" data-${scope}="${element}" aria-label="${esc(info.name)}" title="${esc(info.name)}" aria-pressed="${selected.includes(element)}">${elementLogo(element)}</button>`).join('')}</div>`;
}
function rarityFilters(value,scope){
  const selected=normalizeSelection(value,[1,2,3,4,5,6]);
  return `<div class="icon-filter-group" role="group" aria-label="Filtrer par raretés maximales · plusieurs choix possibles"><button type="button" class="icon-filter all-filter ${selected.length?'':'active'}" data-${scope}="all" aria-pressed="${!selected.length}">Toutes</button>${[1,2,3,4,5,6].map(stars=>`<button type="button" class="icon-filter ${selected.includes(String(stars))?'active':''}" data-${scope}="${stars}" aria-label="${stars} étoiles au maximum" title="${stars} étoiles au maximum" aria-pressed="${selected.includes(String(stars))}">${rarityLogo(stars)}</button>`).join('')}</div>`;
}
function f2pFilter(key){return `<label class="f2p-filter" for="${key}"><input type="checkbox" id="${key}" data-f2p-filter="${key}" aria-describedby="${key}-help" ${ui[key]?'checked':''}><span>F2P uniquement</span></label>`;}
function refreshFilterControls(focusSelector){
  (ui.page==='plan'?renderPlan:renderCollection)();
  document.querySelector(focusSelector)?.focus({preventScroll:true});
}

function image(n,cls='',form=null,variant='icon'){const p=state?.characters[n.id],f=displayForm(n,p,form),src=absolute(variant==='art'?(f.art||f.card||f.clientPortrait):(f.clientIcon||f.clientPortrait||f.portrait||n.clientIcon||n.card));return src?`<img class="${cls}" src="${esc(src)}" alt="${esc(n.name+' — '+displayTitle(n)+' · '+f.stars+'★')}" loading="${variant==='art'?'eager':'lazy'}" referrerpolicy="no-referrer">`:`<span class="portrait-placeholder">${esc(n.name)}</span>`;}
function cardPortrait(n,form=null,showLevel=true){
  const p=state.characters[n.id],f=displayForm(n,p,form),native=cardSprites.byUnitId?.[f.client?.unitId],frame=native?.framePath||cardSprites.framesByRarity?.[f.stars]?.path,label=native?.rarityLabelPath||cardSprites.rarityLabels?.[f.stars]?.path,element=native?.elementPath||Object.values(cardSprites.elementsById||{}).find(e=>e.element===n.element)?.large?.path,u=ultimateStatus(n,p,f),badge=u.status===true?`client-card-sprites/charaicon_status_${u.variant==='red'?'max02':'max'}_txt.png`:null;
  return `<span class="game-card" data-card-rarity="${f.stars}" data-ultimate="${u.status===true?u.variant:'none'}" ${u.status===true?`title="${u.variant==='red'?'Ultimate rouge : vitesse également au maximum':u.variant==='unknown'?'Ultimate : bonus vitesse à renseigner pour connaître la variante':'Ultimate : niveau, capacités, chance et pilules PV/ATK au maximum'}"`:''}>${logoImage(frame,'game-card-frame')}${image(n,'game-card-face',f)}${logoImage(frame,'game-card-frame-edge')}${logoImage(native?.decorationPath,'game-card-decoration')}${logoImage(element,'game-card-element',ELEMENTS[n.element].name)}${logoImage(label,'game-card-rarity',f.stars+' étoiles')}${logoImage(badge,'game-card-ultimate',u.variant==='red'?'Ultimate rouge':'Ultimate')}${showLevel?levelBar(n,p,f):''}</span>`;
}
function levelBar(n,p,f){const lv=levelDisplay(n,p,f);return `<span class="game-level ${lv.kind}" style="--level-color:${lv.color}" title="${lv.level===null?'Niveau à renseigner':lv.kind==='lb'?'Niveau au-delà du plafond normal · Limit Break':''}"><span>Niv.</span><strong>${lv.value}</strong></span>`;}
function ultimateNotice(n,p){
  const u=ultimateStatus(n,p),c=u.conditions.filter(c=>['awakening','level','abilities','hp','atk','luck'].includes(c.key)),labels={awakening:'Éveil',level:'Niveau',abilities:'Capacités',hp:'Pilules PV',atk:'Pilules ATK',luck:'Chance'},title=u.status===true?(u.variant==='red'?'Ultimate rouge atteint':u.variant==='unknown'?'Ultimate atteint · variante à préciser':'Ultimate atteint'):'Conditions du badge Ultimate';
  return `<div class="ultimate-status ${u.status===true?'ready':''}"><strong>${title}</strong><span>${c.map(c=>`${labels[c.key]} : ${fmt(c.actual)} / ${fmt(c.required)}${c.key==='awakening'?'★':''}`).join(' · ')}</span>${u.unknown.length?`<small>À renseigner : ${esc(u.unknown.filter(x=>x!=='Unité de combat').join(', '))}.</small>`:''}${u.status===false&&u.missing.includes('Rareté maximale après éveil')?'<small>Le client exige la rareté maximale de l’arbre d’éveil, y compris ses branches Blazing Awakening.</small>':''}<small>La vitesse au maximum ajoute la variante rouge (${fmt(u.speed.actual)} / ${fmt(u.speed.required)}). ${u.speed.unknown?'Bonus vitesse à renseigner.':''}</small></div>`;
}
function largeArt(n,f){const full=f.largeArtAvailable===true||f.client?.largeArtAvailable===true;return `<figure class="character-art">${image(n,'character-full',f,'art')}<figcaption>${f.stars}★ · ${esc(n.name)}${f.artSource?' · Illustration : GachaWiki':''}${full?'':' · Grand visuel indisponible, portrait agrandi'}</figcaption></figure>`;}

function availability(n){if(n.currentAvailabilityConfirmed)return 'Disponibilité confirmée · captures / ta confirmation';return n.availability==='client_only'?'Disponibilité à confirmer':n.upcoming?'Annoncé': 'Sorti · catalogue communautaire';}
function quantity(r){if(r.neededUnknown)return '<span class="unknown">À préciser</span>';return `${r.exact===false?'<span class="estimate-mark" title="Progression ou hypothèses à préciser">Réf. </span>':''}${fmt(r.needed)}`;}
function missingText(r){return r?.missing===null?`<span class="unknown">${r.awakeningUnknown?'Stocks des matériaux à renseigner':r.exact===false?'Progression à préciser':'Stock à renseigner'}</span>`:r?.missing===0?(r.exact===false||r.neededUnknown||r.awakeningUnknown?'<span class="resource-state unknown">Réf. couverte · à vérifier</span>':'<span class="resource-state ready">✓ Couvert</span>'):fmt(r?.missing);}
function metric(label,value,detail,symbol='◈',orange=false){return `<div class="stat"><span class="stat-label">${label}</span><strong class="stat-value ${orange?'orange':''}">${value}</strong><small class="stat-detail">${detail}</small><span class="stat-symbol">${symbol}</span></div>`;}
function renderPage(){ui.page=routePage(ui.page);updateNav();({collection:renderCollection,plan:renderPlan,sources:renderSources,guide:renderGuide})[ui.page]();document.title=({collection:collectionHeading(),plan:'Plan & stocks',sources:'Sources & sauvegarde',guide:'Guide & missions'})[ui.page]+' · '+accountName()+' · Blazing Collection';}
function renderGuide(){$('#main').innerHTML=renderPlayerGuide({catalogue,lb,ownedCharacters:owned(),charactersState:state.characters,plan:plan(),goals:state.goals,accountMode:state.accountMode,username:accountName(),esc,fmt});}
function collectionActiveFilters(){const filters=collectionFilterSummary(ui);const target=$('#active-collection-filters');if(!target)return;target.innerHTML=filters.map(f=>`<button class="filter-chip" data-action="clear-collection-filter" data-filter-key="${esc(f.key)}" aria-label="Retirer le filtre ${esc(f.label)}">${esc(f.label)} <span aria-hidden="true">×</span></button>`).join('')+`<button class="button compact" data-action="reset-collection-filters">Réinitialiser la recherche et les filtres</button>`;}
function planFilterChips(){const keys={element:'planElement',collectionStars:'planStars',f2pOnly:'planF2pOnly'},filters=collectionFilterSummary({element:ui.planElement,collectionStars:ui.planStars,f2pOnly:ui.planF2pOnly}).map(filter=>({...filter,key:keys[filter.key]}));if(ui.planScope!=='all')filters.unshift({key:'planScope',label:'Personnages : '+({owned:'Possédés',missing:'Manquants',future:'Annoncés'})[ui.planScope]});return filters.map(filter=>`<button class="filter-chip" data-action="clear-plan-filter" data-filter-key="${esc(filter.key)}" aria-label="Retirer le filtre ${esc(filter.label)}">${esc(filter.label)} <span aria-hidden="true">×</span></button>`).join('');}
function resetCollection(){ui=resetCollectionFilters(ui);renderCollection();$('#ninja-search').focus();}
function renderCollection(){
  const box=owned(),p=plan(),abilities=box.reduce((s,n)=>s+(state.characters[n.id].abilities||0),0),known=box.filter(n=>state.characters[n.id].level!==null).length;
  const art=['naruto-uzumaki-no-1-maverick','sasuke-uchiha-lone-survivor','minato-namikaze-rapid-lightning'].map(id=>image(byId.get(id))).join('');
  $('#main').innerHTML=`<section class="hero"><div><div class="eyebrow">Naruto Blazing Revival · ${esc(accountName())}</div><h1>${esc(collectionHeading())}</h1><p>${fmt(all.length)} fiches · ${fmt(catalogue.summary.clientCharacterForms)} formes du client. Les vues ci-dessous couvrent les personnages sortis et les annonces datées. Retrouve ta box et les ressources utiles à ta progression.</p></div><div class="hero-art" aria-hidden="true">${art}</div></section>
  ${isPersonalAccount()&&!box.length?'<section class="import-start"><div><h2>Commencer avec ma box</h2><p>Copie le prompt, joins tes captures dans ChatGPT, puis importe le JSON obtenu. Tu peux aussi ajouter tes personnages manuellement.</p></div><div class="actions-row"><button class="button primary" data-nav="sources">Importer ma box avec ChatGPT</button><button class="button" data-action="start-manual-box">Ajouter mes personnages</button></div></section>':''}
  <section class="stats" aria-label="Résumé de la collection">${metric('Dans ma box',fmt(box.length),`${known} niveaux renseignés`,'◫',true)}${metric('Fiches documentées',fmt(all.length),`${fmt(catalogue.summary.clientCharacterForms)} formes avec images`,'◎')}${metric('Sorties connues',fmt(catalogue.released.length),`${futureCharacters().length} arrivées prévues`,'✦')}</section>
  <div class="journey-steps" aria-label="Parcours de progression"><button class="button" data-nav="guide">Bien démarrer · Guide & missions</button><button class="button" data-nav="plan" data-focus-stocks="true">Renseigner mes stocks</button><button class="button" data-nav="plan">Voir mes ressources manquantes →</button></div>
  <section aria-labelledby="collection-title"><div class="section-heading"><h2 id="collection-title">Ma collection</h2><div class="actions-row"><button class="button compact" data-action="start-entry">Renseigner ma box</button><button class="button compact" data-nav="plan" data-focus-stocks="true">Plan & stocks</button>${isPersonalAccount()?'':'<button class="button compact" data-action="sync">↻ Actualiser Arosa</button>'}<button class="button compact" data-nav="plan">Voir mon plan →</button></div></div>
  <div class="filter-box"><div class="segments" aria-label="Périmètre de la collection">${[['owned','Possédés',box.length],['missing','Manquants',missingCharacters().length],['future','Annoncés',futureCharacters().length]].map(([key,label,count])=>`<button data-scope="${key}" class="${ui.scope===key?'active':''}" aria-pressed="${ui.scope===key}">${label} <small>${count}</small></button>`).join('')}</div><div class="search"><input id="ninja-search" aria-label="Rechercher un personnage" placeholder="Nom, version, numéro ou effet (anglais)…" value="${esc(ui.search)}"></div></div>
  <div class="filters collection-icon-filters"><div class="filter-family"><span>Éléments · choix multiples</span>${elementFilters(ui.element,'element')}</div><div class="filter-family"><span>Rareté maximale · choix multiples</span>${rarityFilters(ui.collectionStars,'collection-stars')}</div>${f2pFilter('f2pOnly')}<select id="collection-filter" aria-label="Filtrer la progression">${(ui.scope==='future'?[['all','Tous les annoncés'],['planned','Dans mon plan']]:[['all','Toute la progression'],['planned','Dans mon plan'],['unknown','Niveau à renseigner'],['lb','Limit Break disponible']]).map(([v,t])=>`<option value="${v}" ${ui.filter===v?'selected':''}>${t}</option>`).join('')}</select><select id="collection-sort" aria-label="Trier les personnages">${(ui.scope==='future'?[['catalogue','Date prévue'],['name','Nom A → Z']]:[['catalogue','Ordre du catalogue'],['name','Nom A → Z'],['stars','Étoiles'],['abilities','Capacités débloquées']]).map(([v,t])=>`<option value="${v}" ${ui.sort===v?'selected':''}>${t}</option>`).join('')}</select><small id="f2pOnly-help" class="filter-hint">F2P : une voie gratuite est documentée. L’obtention actuelle reste à vérifier dans le jeu. Les étoiles désignent la rareté maximale visée, jusqu’à 6★.</small></div>
  <div id="active-collection-filters" class="active-filter-bar" aria-label="Filtres actifs"></div>
  <div class="plan-view-action"><div><strong>Les personnages de cette vue</strong><p id="collection-view-count" class="caption">Selon la vue, la recherche et les filtres ci-dessus, sur tous les résultats.</p></div><div class="plan-view-actions" role="group" aria-label="Actions sur toute la vue filtrée"><button class="button compact" data-action="replace-plan-with-view" aria-describedby="collection-view-count">Mettre comme plan</button><button id="add-view-to-plan" class="button compact" data-action="add-view-to-plan" aria-describedby="collection-view-count">Ajouter au plan</button></div></div>
  <div class="section-heading"><small id="result-count" role="status" aria-live="polite" aria-atomic="true"></small><small>Catégories selon la rareté maximale · portraits selon la forme actuelle</small></div><p class="caption">${ui.scope==='future'?'Ajoute les annoncés au plan pour préparer leurs ressources avant la sortie. Les dates restent indicatives.':ui.scope==='missing'?'Ajoute les personnages manquants au plan pour préparer leurs ressources, ou à ta box si tu les as obtenus.':'Le portrait conserve la rareté de ta forme actuelle, même dans une catégorie supérieure.'}</p><div id="ninja-grid" class="grid"></div><div id="catalogue-more" class="more-cards"></div></section>
  <section class="plan-banner"><div><strong>${p.selected.length} personnages dans ton plan</strong><p>${isPersonalAccount()?'Les stocks non renseignés restent inconnus.':'Stocks à 0 par défaut.'} Les valeurs estimées sont signalées dans les besoins.</p></div><button class="button" data-nav="plan" data-focus-stocks="true">Renseigner mes stocks →</button></section>`;
  renderCards();
}
function filteredCollectionCharacters(){
  const currentStars=maxStarsFor;
  const source=ui.scope==='future'?futureCharacters():ui.scope==='missing'?missingCharacters():owned();
  let rows=source.filter(n=>{const p=state.characters[n.id],query=characterSearchIndexes.get(n.id);return matchesSelection(currentStars(n),ui.collectionStars)&&matchesSelection(n.element,ui.element)&&(!ui.f2pOnly||isF2PCharacter(n))&&matchesCharacterSearch(query,ui.search)&&(ui.filter!=='planned'||p.planned)&&(ui.scope==='future'||ui.filter!=='unknown'||p.level===null)&&(ui.filter!=='six'||currentStars(n)===6)&&(ui.filter!=='five'||currentStars(n)===5)&&(ui.filter!=='four'||currentStars(n)===4)&&(ui.scope==='future'||ui.filter!=='lb'||planningCharacter(n)?.maxing.limitBreak);});
  if(ui.sort!=='catalogue')rows.sort((a,b)=>ui.sort==='name'?a.name.localeCompare(b.name)||a.title.localeCompare(b.title):ui.sort==='stars'?currentStars(b)-currentStars(a)||a.name.localeCompare(b.name):ui.sort==='abilities'?(state.characters[b.id].abilities||0)-(state.characters[a.id].abilities||0):state.characters[a.id].priority-state.characters[b.id].priority||a.name.localeCompare(b.name));
  return rows;
}
function renderCards(){
  const currentStars=maxStarsFor,rows=filteredCollectionCharacters(),viewCount=rows.filter(canUseResourcePlan).length;
  $('#collection-view-count').textContent=`${viewCount} personnage${viewCount===1?'':'s'} éligible${viewCount===1?'':'s'} dans toute cette vue filtrée, même au-delà des résultats affichés. Mettre comme plan remplace la sélection et retire les autres ; Ajouter au plan conserve les autres.${viewCount?'':' Remplacer par cette vue vide videra le plan.'}`;
  $('#add-view-to-plan').disabled=viewCount===0;
  const visible=rows.slice(0,ui.visible);$('#result-count').textContent=`${visible.length} / ${rows.length} fiches affichées · vue ${({owned:'Possédés',missing:'Manquants',future:'Annoncés'})[ui.scope]}`;collectionActiveFilters();
  $('#ninja-grid').innerHTML=rows.length?groups(visible,n=>currentStars(n),n=>{
    const p=state.characters[n.id];if(ui.scope==='future')return futureCard(n);const last=displayForm(n,p),ab=last.abilities.length;
    return `<article class="ninja-card ${p.owned?'is-owned':'missing-card'}" style="--element:${ELEMENTS[n.element].color};--tint:${ELEMENTS[n.element].color}20"><button class="ownership-toggle ${p.owned?'checked':''}" data-owned="${n.id}" role="checkbox" aria-checked="${p.owned}" aria-label="${p.owned?'Retirer':'Ajouter'} ${esc(n.name+' — '+displayTitle(n))}" ${!canEditCharacter(n)?'disabled':''}>${p.owned?'✓':'＋'}</button><button class="card-open" data-open="${n.id}" aria-label="Voir ${esc(n.name+' — '+displayTitle(n))}"><div class="portrait">${cardPortrait(n)}</div>${ui.scope==='future'?`<span class="availability-note future">${releaseDate(n)?'Prévu le '+releaseDate(n):'Date non annoncée'}</span>`:''}<div class="card-body"><h3>${esc(n.name)}</h3><p class="card-subtitle">${esc(displayTitle(n))}${n.variantLabel?` · ${esc(n.variantLabel)}`:''}</p><small class="obtain-chip">${esc(obtainLabel(n))}</small></div></button><div class="ability-icons" aria-label="${p.abilities??'?'} capacités sur ${ab}">${last.abilities.map((a,i)=>`<button data-ability="${i+1}" data-ninja="${n.id}" role="checkbox" aria-checked="${p.abilities!==null&&i<p.abilities}" aria-label="${esc(n.name+' — '+displayTitle(n))} · capacité ${i+1} : ${esc(a.name)}" title="${esc(a.name)} · ${p.abilities===null?'À préciser':i<p.abilities?'Débloquée':'À débloquer'}" ${!p.owned?'disabled':''}>${abilityGraphic(a,p.abilities!==null&&i<p.abilities)}</button>`).join('')}<span>${p.abilities??'?'}/${ab}</span></div><div class="card-actions">${p.owned?`<label class="plan-check"><input type="checkbox" data-plan="${n.id}" ${p.planned?'checked':''} ${canUseResourcePlan(n)?'':'disabled'}>Mon plan</label><button data-progress="${n.id}">Modifier</button>`:ui.scope==='future'?'<span class="unknown">À venir</span>':`${planToggleButton(n,p,'card-plan-button')}<button data-add="${n.id}">Ajouter à ma box</button><button data-open="${n.id}">Fiche ↗</button>`}</div></article>`;
  }):ui.scope==='owned'&&!owned().length?'<div class="empty"><h3>Ta box est vide.</h3><p>Importe les personnages et ressources visibles sur tes captures, ou ajoute tes personnages dans la vue Manquants.</p><button class="button primary" data-nav="sources">Importer ma box avec ChatGPT</button><button class="button" data-action="start-manual-box">Ajouter mes personnages</button></div>':'<div class="empty"><h3>Aucun personnage dans cette vue.</h3><p>Essaie quelques mots du nom ou du titre. Les effets restent en anglais. Tu peux aussi changer de vue ou retirer les filtres.</p><button class="button" data-action="reset-collection-filters">Réinitialiser la recherche et les filtres</button></div>';
  $('#catalogue-more').innerHTML=visible.length<rows.length?`<button class="button" data-action="more-cards">Afficher les ${Math.min(72,rows.length-visible.length)} suivants</button><small>${rows.length-visible.length} fiches supplémentaires</small>`:'';
}
function futureCard(n){const f=previewMaximumForm(n);return `<article class="ninja-card is-announced" style="--element:${ELEMENTS[n.element].color}"><button class="card-open" data-open="${n.id}" aria-label="Voir ${esc(n.name+' — '+displayTitle(n))}"><span class="release-chip"><small>Prévu le</small><strong>${releaseDate(n)}</strong></span><div class="portrait">${cardPortrait(n,f,false)}</div><div class="card-body"><h3>${esc(n.name)}</h3><p class="card-subtitle">${esc(displayTitle(n))}</p><small class="obtain-chip">${esc(obtainLabel(n))}</small><small class="max-preview-label">${f.stars}★ · statistiques au maximum</small></div></button><div class="card-actions">${planToggleButton(n,state.characters[n.id],'card-plan-button')}<button data-open="${n.id}">Voir la fiche ↗</button></div></article>`;}
function groups(rows,stars,render){const standard=[6,5,4,3,2,1].filter(s=>rows.some(n=>stars(n)===s)).map(s=>`<section class="rarity-section"><h3 class="rarity-heading"><span>★ ${s}</span><small>${rows.filter(n=>stars(n)===s).length} fiches affichées</small></h3><div class="rarity-grid">${rows.filter(n=>stars(n)===s).map(render).join('')}</div></section>`).join(''),outside=rows.filter(n=>stars(n)===null);return standard+(outside.length?`<section class="rarity-section"><h3 class="rarity-heading"><span>Formes hors du plan actuel</span><small>${outside.length} fiches · objectifs jusqu’à 6★</small></h3><div class="rarity-grid">${outside.map(render).join('')}</div></section>`:'');}
function resourceRows(rows,editable=true){
  let group='';return rows.sort((a,b)=>resourceInfo(a.key,byId).order-resourceInfo(b.key,byId).order||resourceInfo(a.key,byId).subtitle.localeCompare(resourceInfo(b.key,byId).subtitle)).map(r=>{const info=resourceInfo(r.key,byId);let head='';if(info.group!==group){group=info.group;head=`<tr class="group-row"><td colspan="4">${esc(group)}</td></tr>`;}return head+`<tr><td><div class="resource-label" style="--element:${info.element?ELEMENTS[info.element].color:'#889676'}">${resourceGraphic(info)}<div><strong>${esc(info.name)}</strong><small>${esc(info.subtitle)}</small></div></div></td><td class="num needed" data-needed-key="${esc(r.key)}">${quantity(r)}</td><td class="num">${editable?`<input type="number" min="0" step="1" max="9007199254740991" class="stock-input" data-stock="${esc(r.key)}" aria-label="Stock · ${esc(info.name+' · '+info.subtitle)}" placeholder="Inconnu" value="${state.stocks[r.key]??''}">`:r.stock===null?'<span class="unknown">Inconnu</span>':fmt(r.stock)}</td><td class="num ${r.missing===null?'':'missing'}" data-missing-key="${esc(r.key)}">${missingText(r)}</td></tr>`;}).join('');
}
function ramenMixCounts(counts,element){return [4,3].filter(star=>counts?.[star]>0).map(star=>`<span class="ramen-mix-count">${resourceGraphic(resourceInfo(`ramen:${element}:${star}`,byId))}<strong>${fmt(counts[star])} × ${star}★</strong></span>`).join('')||'<span class="caption">Aucun ramen nécessaire</span>';}
function ramenMixResults(p){const mix=p.ramenMix;if(!mix)return '<p class="caption">Active le mélange des raretés pour optimiser chaque plafond.</p>';return `<p class="help-copy">Estimation selon ton farm : un tiers de 4★ et deux tiers de 3★. Chaque lot contient 1 ramen 4★ et 2 ramen 3★ ; le surplus d’EXP ne change pas cette répartition. Les petits ramen servent uniquement d’ingrédients d’éveil.</p><div class="ramen-mix-grid">${mix.byElement.map(e=>`<div class="ramen-mix-element"><strong>${elementBadge(e.element)}</strong><div class="ramen-mix-counts">${ramenMixCounts(e.counts,e.element)}</div><small>${e.exact?'':'Référence · '}${fmt(e.providedExperience)} EXP fournies · ${fmt(e.wastedExperience)} EXP de surplus</small></div>`).join('')||'<p class="caption">Aucun besoin d’EXP pour cette sélection.</p>'}</div><p class="caption">Calcul séparé à chaque plafond, jusqu’à 6★. Les quantités sont arrondies au lot complet supérieur à chaque plafond. Le ratio est une hypothèse de farm fournie par toi, pas un taux de drop vérifié. La répartition concerne les ramen pour nourrir. Les 3★ utilisés comme ingrédients d’éveil sont indiqués séparément dans les besoins. Les stocks sont ensuite déduits ; les missions nécessaires et le ryō de nourrissage restent à part.</p>${mix.stages.length?`<details class="ramen-chain-detail"><summary>Voir le mélange par personnage et plafond</summary>${mix.stages.map(x=>`<div class="ramen-chain-element"><strong>${esc(x.name+' · '+x.title)} · ${x.stars}★ · niv. ${x.fromLevel} → ${x.toLevel}</strong><div class="ramen-mix-counts">${ramenMixCounts(x.counts,byId.get(x.id)?.element||'Heart')}</div><small>${x.known?'':'Référence · '}${fmt(x.experienceNeeded??x.experienceReference)} EXP nécessaires · ${fmt(x.providedExperience??x.providedExperienceReference)} fournies · surplus ${fmt(x.wastedExperience??x.wastedExperienceReference)}</small></div>`).join('')}</details>`:''}`;}
function ramenAwakeningResults(p){
  const a=p.ramenAwakening;
  if(!a?.enabled)return '<p class="caption">Éveils désactivés : les stocks de chaque rareté sont utilisés directement.</p>';
  if(!a.applicable)return '<p class="caption">Les éveils des stocks demandent des ramen du même élément.</p>';
  const conversions=a.conversions.filter(c=>c.craftCount===null||c.craftCount>0);if(!conversions.length)return '<p class="caption">Aucun surplus de tes stocks ne permet un éveil utile pour ce mélange. Les ramen disponibles sont déduits directement.</p>';
  return `<div class="table-wrap"><table class="ramen-awakening-table"><thead><tr><th>Élément</th><th>Ramen à fabriquer</th><th>Ryō d’éveil</th><th>Encore manquants</th></tr></thead><tbody>${conversions.map(c=>{const star=c.targetStars||4,row=p.rows.find(r=>r.key===`ramen:${c.element}:${star}`);return `<tr><td>${elementBadge(c.element)}</td><td class="num">${c.craftCount===null?'<span class="unknown">À préciser</span>':`${fmt(c.craftCount)} × ${star}★`}</td><td class="num">${c.ryoCost===null?'—':fmt(c.ryoCost)}</td><td class="num">${row?missingText(row):'—'}</td></tr>`;}).join('')}</tbody></table></div><details class="ramen-chain-detail"><summary>Détail des éveils et de leurs matériaux</summary>${conversions.map(c=>`<div class="ramen-chain-element"><strong>${esc(ELEMENTS[c.element]?.name)} · cible ${c.targetStars}★</strong>${(c.steps||[]).slice().sort((a,b)=>a.fromStars-b.fromStars).map(s=>`<small>${s.fromStars}★ → ${s.toStars}★ : ${s.craftCount===null?'à préciser':`${fmt(s.craftCount)} éveil(s) · ${fmt(s.inputCount)} ramen ${s.fromStars}★ · ${fmt(s.ryoCost)} ryō`}</small>`).join('')||'<small>Aucun éveil intermédiaire.</small>'}</div>`).join('')}</details><p class="caption">Les ramen prévus pour nourrir tes personnages sont réservés avant d’éveiller les surplus. Les ingrédients et le ryō d’éveil sont comptés une seule fois ; tes stocks restent inchangés.</p>`;
}
function ramenAwakeningPanel(p){
  const recipes=[{from:1,to:2,count:3,cost:200,gain:'21,21',before:6600,after:8000},{from:2,to:3,count:3,cost:200,gain:'41,67',before:24000,after:34000},{from:3,to:4,count:6,cost:500,gain:'7,84',before:204000,after:220000}];
  return `<section class="panel ramen-awakening-panel"><div class="panel-heading"><h3>Mélange de ramen</h3><span class="tag">Farm estimé · 1:2</span></div><div class="panel-body"><div id="ramen-mix-results">${ramenMixResults(p)}</div><h4 class="other-improvement-heading">Éveiller les surplus de mes stocks</h4><label class="ramen-toggle"><input type="checkbox" data-training="awakenRamen" ${state.training.awakenRamen!==false?'checked':''}>Utiliser les éveils et leurs chaînes</label><div id="ramen-awakening-results">${ramenAwakeningResults(p)}</div><details class="ramen-chain-detail"><summary>Recettes et gain d’EXP</summary>${recipes.map(r=>`<div class="ramen-recipe"><span>${resourceGraphic(resourceInfo(`ramen:Heart:${r.from}`,byId))}<strong>${r.count} × ${r.from}★</strong></span><b>+ ${r.cost} ryō →</b><span>${resourceGraphic(resourceInfo(`ramen:Heart:${r.to}`,byId))}<strong>1 × ${r.to}★</strong></span><div><strong>+${r.gain} % d’EXP</strong><small>${fmt(r.before)} → ${fmt(r.after)} EXP de base</small></div></div>`).join('')}<p class="caption">Quantités totales, ramen de base compris, de même élément. Le bonus d’élément multiplie ces valeurs par 1,5.</p></details></div></section>`;
}
function scrollAwakeningResults(p){
  const report=p.scrollAwakening;if(!report?.enabled)return '<p class="caption">Fusions de parchemins désactivées.</p>';
  const steps=(report.conversions||[]).flatMap(c=>c.steps||[]).filter(s=>s.craftCount>0||s.craftCount===null),count=steps.reduce((sum,x)=>sum+(x.craftCount||0),0);
  if(!steps.length)return '<p class="caption">Aucune fusion nécessaire ou possible avec tes stocks actuels.</p>';
  return `<p class="help-copy">${report.ryoCost===null?'Fusions à préciser selon les stocks et la progression.':`<strong>${fmt(count)} fusion${count===1?'':'s'} à faire</strong> · ${fmt(report.ryoCost)} ryō.`} Seul le surplus est utilisé ; le besoin initial reste réservé.</p><details class="ramen-chain-detail"><summary>Voir les fusions à faire</summary>${steps.map(x=>`<div class="ramen-chain-element"><strong>${esc(ELEMENTS[x.element]?.name)} · ${x.fromStars}★ → ${x.toStars}★ · ${x.craftCount===null?'À préciser':`${fmt(x.craftCount)} fusion${x.craftCount===1?'':'s'}`}</strong><small>${x.craftCount===null?'Stocks ou progression à renseigner':`${fmt(x.inputCount)} parchemins ${x.fromStars}★ → ${fmt(x.craftCount)} parchemins ${x.toStars}★ · ${fmt(x.ryoCost)} ryō`}</small></div>`).join('')}</details><p class="caption">Le manque et le stock après les fusions prévues sont affichés dans les besoins. Une fois les fusions faites dans le jeu, saisis tes stocks réels ; la prévision se recalcule.</p>`;
}

function pillBudgetResults(p){const report=p.pillBudget;if(!report?.stats?.length)return '<p class="caption">Aucun besoin de pilules pour cette sélection.</p>';const labels={hp:'PV',atk:'Attaque',speed:'Vitesse'};return `<div class="pill-allocation-grid">${report.stats.map(s=>`<section class="pill-allocation-card"><h4>${labels[s.stat]}</h4><table><thead><tr><th>Pilule</th><th>Stock</th><th>À utiliser</th><th>Restant</th></tr></thead><tbody>${[2,3].map(star=>`<tr><td><span class="pill-tier">${resourceGraphic(resourceInfo(`pill:${s.stat}:${star}`,byId))}<strong>${star}★</strong></span></td><td>${fmt(s['stock'+star])}</td><td>${fmt(s['used'+star])}</td><td>${fmt(s['remainingStock'+star])}</td></tr>`).join('')}</tbody></table><div class="pill-shortage">${resourceGraphic(resourceInfo(`pill:${s.stat}:3`,byId))}<span>${s.missing3===null?'Quantité à préciser':s.missing3===0?'Stock suffisant':`<strong>${fmt(s.missing3)}</strong> pilules 3★ à obtenir`}</span></div>${s.exact?'':'<small class="caption">Référence selon les valeurs renseignées ; stocks ou progression à préciser.</small>'}</section>`).join('')}</div><p class="caption">« À utiliser » compte uniquement tes pilules disponibles. « À obtenir » est le manque après leur utilisation. Les bonus sont calculés personnage par personnage ; le ryō de fusion reste à part. Tes stocks saisis restent inchangés.</p>`;}
function materialAwakeningResults(p){
  const a=p.materialAwakening;
  if(!a?.enabled)return '<p class="caption">La conversion des autres matériaux est désactivée.</p>';
  if(!a.conversions.length)return '<p class="caption">Aucune autre conversion nécessaire pour les objectifs jusqu’à 6★.</p>';
  return `<div class="table-wrap"><table class="other-material-table"><thead><tr><th>Recette du client</th><th>À fabriquer</th><th>Matériaux à utiliser</th><th>Ryō</th></tr></thead><tbody>${a.conversions.map(c=>`<tr><td><div class="material-recipe-label">${logoImage(c.source.image)}<span>6 × ${esc(c.source.title||c.source.name)} ${c.source.stars}★</span><b>→</b>${logoImage(c.target.image)}<span>1 × ${esc(c.target.title||c.target.name)} ${c.target.stars}★</span></div></td><td class="num">${c.craftCount===null?'À préciser':fmt(c.craftCount)}</td><td class="num">${c.inputCount===null?'—':fmt(c.inputCount)}</td><td class="num">${c.ryoCost===null?'—':fmt(c.ryoCost)}</td></tr>`).join('')}</tbody></table></div><p class="caption">Les matériaux déjà nécessaires à un éveil sont réservés avant la conversion. Chaque stock est utilisé une seule fois ; le coût est ajouté au budget.</p>`;
}
function otherImprovementsPanel(p){
  return `<section class="panel"><div class="panel-heading"><h3>Parchemins & pilules</h3><span class="tag">Données du client</span></div><div class="panel-body"><h4>Fusions de parchemins</h4><p class="help-copy">6 parchemins identiques → 1 de la rareté supérieure, pour 500 ryō : 1★ → 2★, 2★ → 3★ ou 3★ → 4★.</p><label class="ramen-toggle"><input type="checkbox" data-training="awakenScrolls" ${state.training.awakenScrolls!==false?'checked':''}>Utiliser mes surplus et les chaînes de parchemins</label><div id="scroll-awakening-results">${scrollAwakeningResults(p)}</div><p class="caption">Cela peut éviter de farmer un matériau rare. Le gain en énergie dépend des missions disponibles et de leurs récompenses.</p><h4 class="other-improvement-heading">Utiliser les pilules 2★ et 3★</h4><p class="help-copy">Pas d’éveil de pilules : deux 2★ donnent le même bonus qu’une 3★. Les deux stocks sont pris en compte directement.</p><div id="pill-budget-results">${pillBudgetResults(p)}</div><details class="other-material-details"><summary>Autres matériaux d’éveil</summary><p class="caption">Les perles et parchemins spéciaux sont proposés uniquement lorsqu’une amélioration en a besoin.</p><label class="ramen-toggle"><input type="checkbox" data-training="awakenMaterials" ${state.training.awakenMaterials!==false?'checked':''}>Utiliser mes surplus pour les autres recettes du client</label><div id="material-awakening-results">${materialAwakeningResults(p)}</div></details></div></section>`;
}
function remainingSummaryCards(p){
  const values=remainingResourceSummary(p),definitions=[['tokens','Jetons à obtenir','Après déduction de tes jetons','◈'],['ryo','Ryō à obtenir','Éveils et recettes · nourrissage à part','両'],['ramen','Ramen à obtenir','Toutes raretés · stocks et éveils déduits','✦'],['scroll','Parchemins à obtenir','Toutes raretés · stocks et fusions déduits','▤'],['pill','Pilules à obtenir','PV, attaque et vitesse · stocks déduits','◉']];
  return definitions.map(([key,label,detail,symbol])=>{const row=values[key],value=row.value===null?'<span class="unknown">À préciser</span>':`<span class="${row.value===0?'remaining-covered':''}">${fmt(row.value)}</span>`,copy=row.unknownCount?`${row.knownMissing?fmt(row.knownMissing)+' manquants connus · ':''}Stocks ou progression à renseigner`:detail;return metric(label,`<span data-summary="${key}">${value}</span>`,copy,symbol,key==='tokens');}).join('');
}
function renderPlan(){
  const p=plan(),t=state.training;
  $('#main').innerHTML=`<div class="page-intro"><div class="eyebrow">Niveau, Limit Break et pilules</div><h1>Plan & stocks</h1><p>Prépare tes personnages et saisis tes stocks sur cette page. Les ressources encore à obtenir se recalculent après chaque saisie ; les stocks communs sont déduits une seule fois.</p></div>
  <section class="plan-additions"><div><strong>Préparer mes prochains personnages</strong><p>Choisis un personnage manquant ou annoncé, puis clique sur « Ajouter au plan ».</p></div><div class="actions-row"><button class="button compact" data-choose-plan="missing">＋ Choisir des manquants</button><button class="button compact" data-choose-plan="future">＋ Choisir des annoncés</button></div></section>
  <section class="plan-filters"><div class="filter-family plan-scope-family"><span>Personnages du plan</span><div class="segments plan-scope-filters" role="group" aria-label="Filtrer les personnages du plan">${[['all','Tous'],['owned','Possédés'],['missing','Manquants'],['future','Annoncés']].map(([key,label])=>`<button data-plan-scope="${key}" class="${ui.planScope===key?'active':''}" aria-pressed="${ui.planScope===key}">${label}</button>`).join('')}</div></div><div class="filter-family"><span>Éléments · choix multiples</span>${elementFilters(ui.planElement,'plan-element')}</div><div class="filter-family"><span>Rareté maximale · choix multiples</span>${rarityFilters(ui.planStars,'plan-stars')}</div>${f2pFilter('planF2pOnly')}<button class="button compact" data-action="reset-plan-filters">Réinitialiser les filtres</button><small>${p.selected.length} personnage${p.selected.length===1?'':'s'} sélectionné${p.selected.length===1?'':'s'} · totaux pour ce filtre</small><small id="planF2pOnly-help" class="filter-hint">F2P : une voie gratuite est documentée, sans confirmation de l’obtention actuelle. Les filtres portent sur les personnages déjà sélectionnés dans le plan.</small></section>
  <div class="active-filter-bar" aria-label="Filtres actifs du plan">${planFilterChips()}</div>
  <div class="plan-view-action"><div><strong>Ne garder que cette vue dans mon plan</strong><p id="plan-view-count" class="caption">Ne garder dans le plan que les personnages sélectionnés correspondant à ces filtres. ${p.selected.length} personnage${p.selected.length===1?' sera conservé':'s seront conservés'} ; les autres seront retirés du plan.${p.selected.length?'':' Le plan sera vide.'}</p></div><button class="button compact" data-action="replace-plan-with-view" aria-describedby="plan-view-count">Mettre comme plan</button></div>
  <section class="stats plan-summary" aria-label="Ressources restantes après stocks">${remainingSummaryCards(p)}</section>
  ${p.forecastCount?`<div class="notice forecast-notice"><strong>${p.forecastCount} personnage${p.forecastCount===1?'':'s'} à obtenir dans ces totaux${p.announcedCount?`, dont ${p.announcedCount} annoncé${p.announcedCount===1?'':'s'}`:''}.</strong> Prévision depuis la forme de base au niveau 1, sans pilules. Les coûts des annoncés restent à confirmer à leur sortie.</div>`:''}
  <div class="notice">${!p.selected.length?'Choisis des personnages dans la collection pour calculer tes besoins.':p.uncertain?`<strong>${p.uncertain} progressions à compléter.</strong> Les besoins précédés de « Réf. » attendent les informations manquantes.`:p.forecastCount?'Les besoins prévisionnels utilisent les recettes et plafonds du client. Le coût pour obtenir les personnages reste à part.':'Niveaux renseignés. Les pilules, capacités et la chance non visibles sur les captures restent à vérifier.'} Pour le LB, le premier palier permettant d’atteindre le niveau saisi est retenu.</div>
  <section class="panel"><div class="panel-heading"><h3>Mes objectifs de ressources</h3></div><div class="panel-body"><div class="options">${Object.entries({level:'Niveau, éveil & Limit Break',pills:'Pilules PV / attaque / vitesse'}).map(([k,label])=>`<label><input type="checkbox" data-goal="${k}" ${state.goals[k]?'checked':''}>${label}</label>`).join('')}</div><p class="caption">Le coût des capacités et de la chance est masqué. Leurs valeurs restent modifiables dans les fiches et servent au badge Ultimate. Les jetons couvrent les achats nécessaires aux recettes du client.</p></div></section>
  <section class="panel" id="resource-needs" tabindex="-1" aria-labelledby="resource-needs-title"><div class="panel-heading"><h3 id="resource-needs-title">Mes besoins & stocks</h3><div class="search"><input id="resource-search" aria-label="Filtrer les ressources" placeholder="Ramen, parchemins, pilules…" value="${esc(ui.resourceSearch)}"></div></div><div class="panel-body needs-toolbar"><label><input id="only-missing" type="checkbox" ${ui.onlyMissing?'checked':''}>Masquer les autres ressources couvertes</label><button class="button compact" data-action="export-needs">↓ Exporter les manques en CSV</button><small id="needs-count" class="needs-count" role="status" aria-live="polite"></small><p class="caption">Saisis ton stock actuel après chaque run. Ramen, parchemins et pilules restent modifiables même quand leur besoin est couvert. L’export contient seulement les manques et valeurs à préciser.</p></div><div id="resource-sections"></div></section>
  <details class="panel training-panel"><summary>Options du calcul de ramen</summary><div class="panel-body"><div class="options"><label><input type="checkbox" data-training="sameElement" ${t.sameElement?'checked':''}>Même élément (×1,5 EXP)</label><label>Campagne EXP × <input class="multiplier-input" type="number" data-training="campaignMultiplier" min="0.1" max="10" step="0.1" value="${t.campaignMultiplier}"></label><label>Succès de fusion × <input class="multiplier-input" type="number" data-training="successMultiplier" min="0.1" max="10" step="0.1" value="${t.successMultiplier}"></label></div><p class="caption">Ratio de farm estimé : 1 ramen 4★ pour 2 ramen 3★. Les lots couvrent l’EXP à chaque plafond ; le gaspillage ne modifie pas le choix. Pilules 3★ : +10 PV / +4 attaque / +2 vitesse. Pilules 2★ : +5 / +2 / +1. Les deux stocks sont utilisés dans le budget.</p></div></details>
  ${ramenAwakeningPanel(p)}
  ${otherImprovementsPanel(p)}
  <section class="panel"><div class="panel-heading"><h3>Personnages sélectionnés · ${p.selected.length}</h3></div><div class="panel-body selected-list">${p.selected.map(n=>selectedPlanCharacter(n,p.plans.find(x=>x.id===n.id))).join('')||'<p class="help-copy">Choisis un personnage ci-dessus ou coche « Mon plan » dans ta collection.</p>'}</div></section>`;
  renderPlanRows();
}

function selectedPlanCharacter(n,calc){
  const p=state.characters[n.id],label=p.owned?'Possédé':n.upcoming?'Annoncé · '+(releaseDate(n)||'date à préciser'):'À obtenir';
  return `<div class="selected-ninja ${p.owned?'':'is-forecast'}">${image(n)}<div class="selected-character-copy"><strong>${esc(n.name)}</strong><small>${esc(displayTitle(n))} · objectif niveau ${calc.target??'à préciser'}</small><span class="tag ${p.owned?'':'forecast-tag'}">${esc(label)}</span><small>${calc.forecast?'Prévision · forme de base, niveau 1':calc.uncertain.length?`${calc.uncertain.length} informations à compléter`:'Progression renseignée'} · ${fmt(calc.requirements.tokens||0)} jetons</small></div><div class="selected-character-actions"><button class="button compact" ${p.owned?`data-progress="${n.id}"`:`data-needs="${n.id}"`}>${p.owned?'Renseigner':'Voir les besoins'}</button><button class="button compact ghost" data-toggle-plan="${n.id}" aria-label="Retirer du plan · ${esc(n.name+' — '+displayTitle(n))}">Retirer</button></div></div>`;
}
function planEntryRows(p){return resourceEntryRows(p.rows,state.stocks,Object.keys(ELEMENTS));}
function searchedResourceRows(p){const terms=normalizeSearch(ui.resourceSearch).split(' ').filter(Boolean);return planEntryRows(p).filter(r=>{const v=resourceInfo(r.key,byId),label=normalizeSearch(`${v.name} ${v.subtitle} ${v.group}`);return terms.every(term=>label.includes(term));});}

function renderPlanRows(){const p=plan(),searched=searchedResourceRows(p),rows=visibleResourceEntryRows(searched,ui.onlyMissing);$('#resource-sections').innerHTML=rows.length?resourceSections(rows,true):`<div class="empty"><h3>${ui.resourceSearch?'Aucune ressource dans cette recherche.':p.selected.length?'Aucun manque à afficher.':'Aucun personnage sélectionné.'}</h3><p>${ui.resourceSearch?'Efface la recherche pour revoir tes ressources.':p.selected.length?'Les besoins connus de cette sélection sont couverts. Décoche le filtre pour voir tous les stocks et besoins.':'Choisis des personnages possédés, manquants ou annoncés pour préparer leurs ressources.'}</p>${!p.selected.length?'<button class="button" data-nav="collection">Choisir mes personnages</button>':''}</div>`;renderedResourceKeys=rows.map(r=>r.key);updateNeedsSummary(p,rows,searched);}
let renderedResourceKeys=[],planRowsDirty=false;
function updateNeedsSummary(p,rows,searched){const count=$('#needs-count');if(count)count.textContent=`${rows.length} stocks affichés · ${p.selected.length} personnages dans ce filtre · les champs de farm restent accessibles`;const exporter=document.querySelector('[data-action="export-needs"]');if(exporter)exporter.disabled=!actionableResourceRows(searched).length;}
function refreshPlanRowsAfterEntry(){const p=plan(),searched=searchedResourceRows(p),rows=visibleResourceEntryRows(searched,ui.onlyMissing),keys=rows.map(r=>r.key);if(keys.length===renderedResourceKeys.length&&keys.every(key=>renderedResourceKeys.includes(key))){updateNeedsSummary(p,rows,searched);return;}const focusKey=document.activeElement?.dataset.stock;renderPlanRows();if(focusKey){const field=[...document.querySelectorAll('#resource-sections [data-stock]')].find(input=>input.dataset.stock===focusKey);field?.focus({preventScroll:true});}}
function exportNeeds(){const p=plan(),rows=actionableResourceRows(searchedResourceRows(p));if(!rows.length){notify('Aucun manque à exporter pour ce filtre.');return;}const scope=`${({all:'Tous les personnages',owned:'Possédés',missing:'Manquants',future:'Annoncés'})[ui.planScope]} · ${p.forecastCount} prévision(s) depuis niveau 1 · ${selectionText(ui.planElement,FILTER_VALUES.planElement,value=>ELEMENTS[value].name,'Tous les éléments')} · ${selectionText(ui.planStars,FILTER_VALUES.planStars,value=>value+'★','Toutes les raretés')} · ${ui.planF2pOnly?'F2P uniquement':'Toutes les obtentions'} · ${p.selected.length} personnages · recherche ${ui.resourceSearch||'aucune'}`,date=new Intl.DateTimeFormat('fr-CH',{dateStyle:'short',timeZone:'Europe/Zurich'}).format(new Date()),csv=resourceNeedsCsv(rows,{resourceInfo:key=>resourceInfo(key,byId),scope,date}),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='blazing-ressources-manquantes.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Liste des manques exportée. Les stocks sont inchangés.');}
function resourceSections(rows,editable=false){
  const other=rows.filter(r=>!['ramen','scroll','pill'].includes(r.key.split(':')[0]));
  return `${other.length?`<div class="table-wrap"><table><thead><tr><th>Ressource</th><th>Besoin</th><th>Mon stock</th><th>Manque</th></tr></thead><tbody>${resourceRows(other,editable)}</tbody></table></div>`:''}${resourceMatrix('ramen','Ramen',rows,editable)}${resourceMatrix('scroll','Parchemins',rows,editable)}${resourceMatrix('pill','Pilules',rows,editable)}${rows.length?'':'<div class="empty">Aucun besoin pour cette sélection.</div>'}`;
}
function matrixColumns(kind){return kind==='pill'?[['hp','PV'],['atk','Attaque'],['speed','Vitesse']]:Object.entries(ELEMENTS).map(([e,v])=>[e,v.name]);}
function resourceMatrix(kind,title,rows,editable=false){
  const columns=matrixColumns(kind),map=new Map(rows.map(r=>[r.key,r])),stars=(kind==='ramen'?[4,3,2,1]:[1,2,3,4]).filter(s=>columns.some(([id])=>map.has(`${kind}:${id}:${s}`)));
  if(!stars.length)return'';
  return `<section class="resource-matrix"><h3>${title}</h3><div class="table-wrap"><table class="matrix-table ${kind==='pill'?'pill-matrix':'element-matrix'}"><thead><tr><th>Rareté</th>${columns.map(([id,label])=>`<th>${kind==='pill'?label:elementBadge(id)}</th>`).join('')}</tr></thead><tbody>${stars.map(s=>`<tr><th scope="row">${s}★</th>${columns.map(([id])=>{const key=`${kind}:${id}:${s}`,r=map.get(key);return `<td>${r?matrixNeed(r,editable):'<span class="no-need">—</span>'}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div></section>`;
}

function needRole(r){return r?.key.startsWith('scroll:')?'Besoin initial':(r?.craftConsumed??r?.awakeningNeeded)>0?((r.directNeeded??r.feedingNeeded)>0?'Besoins + éveils':'Pour éveil'):'Besoin';}
function craftedNote(r){return r?.craftedCount>0?`${fmt(r.craftedCount)} ${r.key.startsWith('scroll:')?'obtenus par fusion':'à fabriquer'}`:'';}
function needBreakdownText(r){
  if(r?.key.startsWith('scroll:')){
    const consumed=r.craftConsumed??r.awakeningNeeded,star=Number(r.key.split(':')[2]),parts=[];
    if(consumed===null)parts.push('Fusions à préciser');
    else if(consumed>0)parts.push(`${fmt(consumed/6)} fusion${consumed===6?'':'s'} → ${star+1}★`);
    if((consumed>0||r.craftedCount>0||consumed===null)&&r.remainingStockAfterCraft!==undefined)parts.push(`Stock après fusions : ${fmt(r.remainingStockAfterCraft)}`);
    return parts.join(' · ');
  }
  if(r?.key.startsWith('ramen:')&&r.feedingNeeded!==undefined)return `Nourrir : ${fmt(r.feedingNeeded)}${r.awakeningNeeded===null?' · Éveils : à préciser':r.awakeningNeeded>0?` · Éveils : ${fmt(r.awakeningNeeded)}`:''}`;
  return '';
}
function matrixNeed(r,editable){const info=resourceInfo(r.key,byId),label=needRole(r);return `<div class="matrix-cell">${resourceGraphic(info)}<strong data-needed-key="${esc(r.key)}">${quantity(r)}</strong><small data-need-role="${esc(r.key)}">${label}</small><small class="need-breakdown" data-need-breakdown="${esc(r.key)}">${needBreakdownText(r)}</small>${editable?`<small class="matrix-stock-label">Mon stock actuel</small><input type="number" min="0" step="1" class="stock-input" data-stock="${esc(r.key)}" aria-label="Stock · ${esc(info.name)}" placeholder="Mon stock" value="${state.stocks[r.key]??''}">`:`<small>Stock : ${r.stock===null?'Inconnu':fmt(r.stock)}</small>`}<small class="crafted-note" data-crafted-key="${esc(r.key)}">${craftedNote(r)}</small><small class="matrix-missing">À obtenir : <span data-missing-key="${esc(r.key)}">${missingText(r)}</span></small></div>`;}
function refreshBudgetUi(){
  const p=plan(),map=new Map(planEntryRows(p).map(r=>[r.key,r]));
  const summary=document.querySelector('.plan-summary');if(summary)summary.innerHTML=remainingSummaryCards(p);
  document.querySelectorAll('[data-missing-key]').forEach(el=>el.innerHTML=missingText(map.get(el.dataset.missingKey)||{missing:0}));
  document.querySelectorAll('[data-needed-key]').forEach(el=>el.innerHTML=quantity(map.get(el.dataset.neededKey)||{needed:0}));
  document.querySelectorAll('[data-need-role]').forEach(el=>{const r=map.get(el.dataset.needRole);el.textContent=needRole(r);});
  document.querySelectorAll('[data-need-breakdown]').forEach(el=>{const r=map.get(el.dataset.needBreakdown);el.textContent=needBreakdownText(r);});
  document.querySelectorAll('[data-crafted-key]').forEach(el=>{const r=map.get(el.dataset.craftedKey);el.textContent=craftedNote(r);});
  document.querySelectorAll('[data-stock-need]').forEach(el=>{const r=map.get(el.dataset.stockNeed)||{needed:0,exact:true};el.innerHTML=`Besoin : ${quantity(r)}`;});
  const mixResults=$('#ramen-mix-results');if(mixResults)mixResults.innerHTML=ramenMixResults(p);
  const results=$('#ramen-awakening-results');if(results)results.innerHTML=ramenAwakeningResults(p);
  const scrollResults=$('#scroll-awakening-results');if(scrollResults)scrollResults.innerHTML=scrollAwakeningResults(p);
  const pillResults=$('#pill-budget-results');if(pillResults)pillResults.innerHTML=pillBudgetResults(p);
  const materialResults=$('#material-awakening-results');if(materialResults)materialResults.innerHTML=materialAwakeningResults(p);
}


function accountStockKeys(){return [...new Set([...resourceStockKeys(all.filter(n=>state.characters[n.id].owned||state.characters[n.id].planned&&canPlanCharacter(n))),...Object.entries(state.stocks).filter(([key,v])=>v>0&&(key==='shard'||key.startsWith('material:')&&materialsById.get(Number(key.split(':')[1]))?.category!==94)).map(([key])=>key)])];}

function photoImportPanel(){return `<section class="panel photo-import-panel" aria-labelledby="photo-import-title"><div class="panel-heading"><h2 id="photo-import-title">Importer ma box avec ChatGPT</h2></div><div class="panel-body"><ol class="photo-import-steps"><li><h3>1. Copier le prompt</h3><p>Ce texte demande de relever uniquement les informations visibles et de laisser les autres inconnues.</p><button class="button primary" data-action="copy-import-prompt">Copier le prompt</button><a href="import-box-prompt.txt" download class="import-download">Télécharger le prompt</a></li><li><h3>2. Ajouter mes captures</h3><p>Colle le prompt dans ChatGPT, puis joins les images de tes personnages et de tes ressources. Ajoute des captures lisibles des formes et niveaux.</p><a class="button" href="https://chatgpt.com/" target="_blank" rel="noopener noreferrer">Ouvrir ChatGPT ↗</a></li><li><h3>3. Importer le JSON obtenu</h3><p>Récupère le fichier JSON généré et importe-le ici. L’import remplace ta box : conserve une sauvegarde avant de changer de relevé.</p><button class="button" data-action="import-file">Importer un fichier JSON</button></li></ol><p id="copy-prompt-status" class="import-status" role="status" aria-live="polite" tabindex="-1"></p><div id="import-prompt-fallback" class="import-prompt-fallback" hidden><label for="import-prompt-text">Prompt à copier manuellement</label><textarea id="import-prompt-text" readonly rows="10" aria-describedby="copy-prompt-status"></textarea></div><details class="import-reference-details"><summary>Fichiers de référence si ChatGPT en a besoin</summary><p class="help-copy">Si ChatGPT ne peut pas lire les références du site, joins aussi le fichier de référence à tes images.</p><div class="source-links"><a href="box-import-reference.json" download>Télécharger la référence des personnages et ressources</a><a href="box-import.schema.json" download>Format JSON détaillé</a></div></details></div></section>`;}
function importFeedbackHtml(){
  const notes=importFeedback?.notes||(isPersonalAccount()?state.importNotes:[])||[],message=importFeedback?.message||(notes.length?'Observations conservées lors de ton import :':'');
  return `<div id="box-import-status" class="import-status ${importFeedback?.error?'error':''}" role="${importFeedback?.error?'alert':'status'}" aria-live="polite" tabindex="-1">${message?`<p>${esc(message)}</p>`:''}${notes.length?`<details><summary>${notes.length} observation${notes.length===1?'':'s'} à vérifier</summary><ul>${notes.slice(0,5).map(note=>`<li>${esc(note)}</li>`).join('')}</ul>${notes.length>5?`<p class="caption">${notes.length-5} autres observations sont conservées dans la sauvegarde JSON.</p>`:''}</details>`:''}</div>`;
}
function renderSources(){
  $('#main').innerHTML=`<div class="page-intro"><div class="eyebrow">Des données consultables, des calculs transparents</div><h1>Sources & sauvegarde</h1><p>Client NBRC3.00.032 : ${fmt(catalogue.summary.clientCharacterForms)} formes, regroupées en ${fmt(all.length)} fiches avec leurs images. Les grandes illustrations manquantes sont complétées par GachaWiki lorsqu’une correspondance de carte est confirmée. La disponibilité associe la référence communautaire du 13 octobre et les confirmations documentées du 14 octobre. Les objectifs de progression sont limités à 6★ pour le moment.</p></div>
  ${photoImportPanel()}
<div class="two-column"><section class="panel"><div class="panel-heading"><h3>Ta collection, conservée chez toi</h3></div><div class="panel-body"><p class="help-copy">${isPersonalAccount()?'Ta box personnelle contient tes saisies et les informations visibles sur tes captures.':'Ta box publique Arosa et tes captures servent de point de départ.'} Niveaux, capacités, chance, pilules et stocks sont modifiables. Les personnages manquants et annoncés peuvent entrer au plan sans être ajoutés à la box ; leurs ressources sont prévues depuis la forme de base au niveau 1, sans pilules. Les changements sont sauvegardés sur ce navigateur.</p>${isPersonalAccount()?'':`<p class="help-copy">Might Guy « Jeunesse bouillante » a été ajouté depuis ta confirmation du cadeau des 100k inscriptions. Il a été reçu en 6★ au niveau 100 (MAX normal), sans Limit Break ; ses bonus restent à renseigner. </p>`}<p class="help-copy">Exporte une sauvegarde JSON pour transférer ta progression ou la conserver avant de changer de navigateur.</p><div class="backup-actions"><button class="button primary" data-action="export">↓ Exporter ma sauvegarde</button><button class="button" data-action="import-file">↑ Importer un fichier JSON</button><input id="backup-file" type="file" accept="application/json,.json" hidden></div><textarea class="backup-text" id="backup-text" aria-label="Sauvegarde JSON à importer" placeholder="Ou colle ici le JSON de ta box ou une sauvegarde…"></textarea><button class="button compact" data-action="import-text">Importer le JSON collé</button>${importFeedbackHtml()}</div></section>
  ${isPersonalAccount()?`<section class="panel"><div class="panel-heading"><h3>Références du catalogue</h3></div><div class="panel-body"><ul class="source-list"><li><a href="https://gachawiki.net/naruto-blazing" target="_blank" rel="noopener">Catalogue communautaire GachaWiki ↗</a></li><li><a href="catalogue.json" download="naruto-client-catalogue-complet.json">Télécharger le catalogue complet JSON ↓</a></li><li><a href="box-import-reference.json" download>Référence à joindre à ChatGPT ↓</a></li></ul><p class="caption">Les données du catalogue servent à reconnaître les formes. Seules tes saisies et les informations effectivement observées renseignent ta box.</p></div></section>`:`  <section class="panel"><div class="panel-heading"><h3>Références & import Arosa</h3></div><div class="panel-body"><ul class="source-list"><li><a href="https://gachawiki.net/profile/Arosa/naruto-blazing" target="_blank" rel="noopener">Box publique Arosa ↗</a></li><li><a href="https://gachawiki.net/naruto-blazing" target="_blank" rel="noopener">Catalogue communautaire GachaWiki ↗</a></li><li><a href="https://docs.google.com/spreadsheets/d/e/2PACX-1vQo0o9mYoatBOssmhpunMYRem9DjJyXrEL1fOSjXP3jxePRvWZxhl69iR8zp_mHX09K6CnH2PmHtnRk/pubhtml#gid=308125820" target="_blank" rel="noopener">Guide communautaire fourni ↗</a></li><li><a href="catalogue.json" download="naruto-client-catalogue-complet.json">Télécharger le catalogue complet JSON ↓</a></li></ul><p class="caption">Dernier import Arosa : ${esc(new Date(state.importedAt).toLocaleString('fr-CH',{timeZone:'Europe/Zurich'}))}. Actualisation par GET des données publiques ; tes corrections manuelles sont conservées.</p><div class="backup-actions"><button class="button" data-action="sync">↻ Actualiser la box Arosa</button></div><p class="caption">Import des captures du 14/10 : 80 cartes physiques, 78 versions, 43 types de matériaux. Les capacités, pilules et la chance non visibles restent à vérifier dans les fiches ; seules les valeurs confirmées ont été reprises. </p></div></section>`}</div>
  <section class="panel"><div class="panel-heading"><h3>Disponibilité actuelle des personnages</h3><span class="tag">Preuves par forme</span></div><div class="panel-body"><p class="help-copy">Les captures et confirmations documentées du compte de référence prouvent ${fmt(catalogue.summary.currentConfirmedForms)} formes dans ${fmt(catalogue.summary.currentConfirmedFamilies)} fiches. Cette confirmation de disponibilité n’ajoute aucun personnage à ta box personnelle.</p><p class="help-copy">Les fichiers du client contiennent aussi les personnages et missions historiques. Leurs champs « actifs » ne permettent donc pas de déterminer ce qui est obtenable aujourd’hui.</p><p class="help-copy">Le calendrier des missions et les listes d’invocation actuelles sont envoyés par le serveur. Ces réponses sont absentes des fichiers récupérés. Les bannières téléchargées récemment ne prouvent pas qu’un événement est encore ouvert.</p><p class="caption">Inspection du 14 octobre 2026. Les 88 sorties et les 36 annonces initiales restent une référence communautaire datée. Les formes supérieures non vues ne sont pas confirmées par la présence d’une forme de base. <a href="collection-catalogue-reconciliation.json" download>Rapprochement des 124 fiches GachaWiki ↓</a> · <a href="availability-audit.json" download>Résultat de la vérification ↓</a></p></div></section>
  <section class="panel"><div class="panel-heading"><h3>Cartes & badge Ultimate</h3><span class="tag">Images et règle du client</span></div><div class="panel-body"><p class="help-copy">Fonds et cadres natifs pour les sept raretés, symboles d’élément, étoiles et variantes Blazing Awakening / Legendary. Les portraits possédés restent en couleur ; la coche indique la possession. Le placement reprend la géométrie native pour aligner l’image sur l’intérieur du cadre. <a href="card-fit-audit.json" download>Vérification de l’alignement ↓</a></p><p class="help-copy">« Ultimate » exige la rareté maximale de l’arbre d’éveil, le niveau maximal avec Limit Break, toutes les capacités, la chance maximale et les pilules PV / ATK au plafond. Les pilules vitesse au maximum ajoutent le badge rouge. La règle utilise la forme actuellement possédée et les données renseignées dans « Ma progression ».</p><p class="caption">Une forme 5★ peut donc afficher « Ultimate » quand cette version atteint sa rareté maximale en 5★, comme certaines versions de Sakura. <a href="ultimate-rule-audit.json" download>Vérification de la règle du client ↓</a></p></div></section>
  <section class="panel"><div class="panel-heading"><h3>Niveaux sous les portraits</h3></div><div class="panel-body"><p class="help-copy">Le niveau est blanc jusqu’au plafond normal de la forme actuelle, rouge au-delà. Le plafond final atteint affiche « MAX » : rouge avec Limit Break, jaune sans Limit Break. La saisie et le budget se basent uniquement sur le niveau.</p><p class="caption">Dans le jeu, la couleur rouge dépend d’un palier LB acheté. Un achat réalisé avant de dépasser le plafond normal ne peut pas être déduit du niveau seul. <a href="level-rule-audit.json" download>Vérification de la règle native ↓</a></p></div></section>

  <section class="panel"><div class="panel-heading"><h3>Calculs & précision</h3></div><div class="panel-body"><ul class="source-list"><li><strong>Recettes du client :</strong> éveil, paliers LB, fabrication et ryō. Les achats sont regroupés en jetons, sans compter deux fois les matériaux de fabrication.</li><li><strong>Parchemins 3★ :</strong> 16 dans la recette 6★ complète du client ; l’ancienne marge communautaire n’est plus appliquée.</li><li><strong>EXP :</strong> courbes individuelles du client. Le niveau se renseigne dans la fiche ; le calcul part du début de ce niveau et le palier LB en est déduit.</li><li><strong>Ramen :</strong> Estimation selon le ratio de farm indiqué : 1 ramen 4★ pour 2 ramen 3★, arrondi au lot complet supérieur à chaque plafond. Les 1★/2★ sont réservés aux recettes d’éveil. Le surplus est affiché mais ne sert pas à choisir les quantités. Le ratio approximatif est fourni par le joueur, pas confirmé par les données du serveur. Multiplicateurs explicites ; ryō de nourrissage à part.</li><li><strong>Éveil des ramen :</strong> trois 1★ donnent un 2★ pour 200 ryō (+21,21 % d’EXP), trois 2★ donnent un 3★ pour 200 ryō (+41,67 %), six 3★ donnent un 4★ pour 500 ryō (+7,84 %). Les besoins directs de chaque rareté sont réservés avant d’éveiller les surplus des stocks. Le ratio de farm est appliqué avant la déduction des stocks ; le temps de farm dépend aussi des missions disponibles. <a href="ramen-awakening-audit.json" download>Recettes natives ↓</a> · <a href="ramen-mix-audit.json" download>Vérification du mélange ↓</a></li><li><strong>Parchemins :</strong> six parchemins identiques donnent un de la rareté supérieure pour 500 ryō. Le besoin affiché reste le besoin initial des personnages. Le surplus réservé pour les fusions est indiqué séparément, et les parchemins obtenus réduisent le manque supérieur. Le temps de farm économisé dépend des récompenses et événements disponibles.</li><li><strong>Pilules :</strong> plafonds 6★ +300 PV / +100 ATK / +30 vitesse. Les formes 7★ sont conservées à titre documentaire et exclues du plan actuel. Gains 3★ +10 / +4 / +2, gains 2★ +5 / +2 / +1. Aucune recette d’éveil de pilules ; les deux raretés s’utilisent directement.</li><li><strong>Autres recettes :</strong> les perles et parchemins spéciaux sont convertis seulement si leur cible est nécessaire au plan jusqu’à 6★. 179 conversions de matériaux vérifiées dans le client. Les recettes nécessaires au LB sont déjà incluses dans le budget de jetons. <a href="material-awakening-audit.json" download>Vérification complète ↓</a> · <a href="material-recipes.json" download>Toutes les recettes ↓</a></li><li><strong>Chance :</strong> plafond par rareté confirmé. La chance reste une progression à renseigner ; son coût est masqué.</li><li><strong>Stocks :</strong> ${isPersonalAccount()?'inconnus tant qu’ils ne sont pas renseignés ou observés sur tes captures':'à 0 par défaut pour le profil historique Arosa'} ; une case vidée reste inconnue. Le manque réel attend les informations nécessaires.</li><li><strong>Disponibilité :</strong> les ${catalogue.clientOnly.length} autres fiches sont présentes dans le client ; leur disponibilité actuelle sur le serveur reste à confirmer. Les variantes Blazing Awakening ont des fiches séparées.</li></ul></div></section>
<p class="caption">Données du client installé et de GachaWiki / Naruto Blazing Wiki. Les illustrations appartiennent à leurs ayants droit. Les contributions communautaires sont attribuées sous <a href="https://creativecommons.org/licenses/by-sa/3.0/" target="_blank" rel="noopener">CC BY-SA 3.0</a>.</p>`;
}
function openCharacter(id,tab='fiche'){
  ui.dialogId=id;const n=byId.get(id),p=state.characters[id];
  ui.tab=tab==='progress'&&!p.owned?'resources':tab;
  if(ui.tab==='progress'&&!canEditCharacter(n)||ui.tab==='resources'&&!canUseResourcePlan(n))ui.tab='fiche';
  const f=p.owned&&canEditCharacter(n)?displayForm(n,p):previewMaximumForm(n);ui.form=f.client.unitId;
  renderDialog();if(!$('#character-dialog').open)$('#character-dialog').showModal();
}
function renderDialog(){
  const n=byId.get(ui.dialogId),p=state.characters[n.id],goal=planningCharacter(n),editable=canEditCharacter(n)&&p.owned,plannable=canUseResourcePlan(n),shown=n.forms.find(f=>f.client.unitId===ui.form)||n.forms.at(-1);
  if(ui.tab==='progress'&&!editable)ui.tab=plannable?'resources':'fiche';if(ui.tab==='resources'&&!plannable)ui.tab='fiche';
  const tabs=[['fiche',editable?'Fiche complète':'Statistiques au maximum'],...(editable?[['progress','Ma progression']]:[]),...(plannable?[['resources',p.owned?'Mes besoins':'Besoins prévisionnels']]:[])];
  $('#dialog-content').innerHTML=`<div class="dialog-head">${cardPortrait(n,ui.tab==='fiche'?shown:null,editable)}<div><div class="eyebrow">Fiche personnage</div><h2 id="dialog-title">${esc(n.name)}</h2><p>${esc(displayTitle(n))}</p><div class="dialog-badges">${elementBadge(n.element)}<span class="tag">${ui.tab==='fiche'?shown.stars:goal?.maxStars??'—'}★ · plafond ${ui.tab==='fiche'?shown.client.finalCap:goal?.maxing.targetLevel??'—'}</span><span class="tag">${p.owned?'Dans ma box':availability(n)}</span>${p.planned?'<span class="tag">Dans mon plan</span>':''}</div></div><button class="dialog-close" data-action="close-dialog" aria-label="Fermer la fiche">×</button></div><div class="dialog-tabs" role="tablist" aria-label="Onglets de la fiche">${tabs.map(([k,label])=>`<button role="tab" aria-selected="${ui.tab===k}" data-tab="${k}" class="${ui.tab===k?'active':''}">${label}</button>`).join('')}</div><div class="dialog-body" id="dialog-body"></div>`;
  ({fiche:renderFiche,progress:renderProgress,resources:renderNeeds})[ui.tab](n,p);
}

function skill(title,s){if(!s)return'';return `<section class="skill-block"><div class="skill-kind">${title}</div><h3>${esc(s.name)}</h3><p>${esc(s.text)}</p>${s.textNwus?`<p><strong>PvP :</strong> ${esc(s.textNwus)}</p>`:''}${s.detailsMissing?.length?`<p class="caption">À confirmer : ${esc(s.detailsMissing.join(', '))}</p>`:''}<div class="skill-meta">Chakra : ${s.chakra??'—'} · ${s.hits??'—'} coups · ${esc(s.range||'—')} · ${esc(s.shape||'')}</div></section>`;}
function renderFiche(n,p){
  const editable=canEditCharacter(n),forms=editable?n.forms:planningCharacter(n)?.forms||n.forms,f=forms.find(x=>x.client.unitId===ui.form)||forms.at(-1),plus=f.stats.plusValues;
  $('#dialog-body').innerHTML=`<div class="form-picker"><div><h3>Statistiques & techniques</h3><small class="unknown">Valeurs au plafond, avec pilules et capacités permanentes</small></div><select id="detail-form" aria-label="Forme de la fiche">${forms.map(x=>`<option value="${x.client.unitId}" ${f.client.unitId===x.client.unitId?'selected':''}>${x.stars}★ · carte #${x.cardNo} · niv. ${x.limitBreak?x.maxLvLb:x.maxLv}</option>`).join('')}</select></div>
  <div class="character-overview">${largeArt(n,f)}<div class="character-overview-info"><div class="fact-list"><span>Coût : <strong>${fmt(f.cost.base)}${f.cost.reduced===null?'':` → ${fmt(f.cost.reduced)}`}</strong></span><span>Chance : <strong>${f.luck.min===null?'—':f.luck.min} → ${f.luck.max}</strong></span><span>Portée : <strong>${esc(f.range)}</strong></span><span>Coups normaux : <strong>${fmt(f.normalHits)}</strong></span><span>${esc(f.affiliations.join(' · '))}</span></div>
  <section class="panel"><div class="table-wrap"><table class="stat-table"><thead><tr><th>Statistique</th><th class="num">Max normal</th><th class="num">Max LB</th><th class="num">Pilules max</th><th class="num">Base + pilules + bonus fixes</th></tr></thead><tbody>${[['missions','hp','PV · Missions'],['missions','atk','ATK · Missions'],['nwus','hp','PV · PvP'],['nwus','atk','ATK · PvP'],['nwus','speed','Vitesse · PvP']].map(([mode,key,label])=>`<tr><td>${label}</td><td class="num">${fmt(f.stats[mode][key]?.max)}</td><td class="num">${fmt(f.stats[mode][key]?.maxLb)}</td><td class="num">+${plus[key]||0}</td><td class="num needed">${fmt(maximumStat(f,mode,key))}</td></tr>`).join('')}</tbody></table></div></section>
  </div></div><div class="two-column"><div>${skill('Ninjutsu',f.ninjutsu)}${skill('Technique ultime',f.secretTechnique)}</div><div><section class="skill-block"><div class="skill-kind">Terrain · Field Skill</div><p>${esc(f.fieldSkill)}</p></section><section class="skill-block"><div class="skill-kind">Soutien · Buddy Skill</div><p>${esc(f.buddySkill)}</p></section></div></div>
  ${editable?`<section class="panel"><div class="panel-heading"><h3>Capacités</h3><span class="badge-count">${p.abilities??'?'} / ${f.abilities.length}</span></div><div class="panel-body"><div class="ability-icons progress-ability-icons" aria-label="Capacités débloquées">${f.abilities.map((a,i)=>`<button type="button" data-fiche-ability="${i+1}" role="checkbox" aria-checked="${p.owned&&p.abilities!==null&&i<p.abilities}" aria-label="Capacité ${i+1} : ${esc(a.name)}" title="${esc(a.name)}" ${!p.owned||f.client.unitId!==displayForm(n,p).client.unitId?'disabled':''}>${abilityGraphic(a,p.owned&&p.abilities!==null&&i<p.abilities)}</button>`).join('')}</div><small class="caption">Clique sur les icônes pour renseigner les capacités de ta forme actuelle.</small><details class="ability-description-list"><summary>Lire les effets des capacités</summary>${f.abilities.map(a=>`<div class="ability-item"><div><strong>${esc(a.name)}</strong><p>${esc(a.text)}</p>${a.textNwus?`<p>PvP : ${esc(a.textNwus)}</p>`:''}</div></div>`).join('')||'<p>Aucune capacité.</p>'}</details></div></section>`:''}
  ${f.syncSkills.length?`<section class="panel"><div class="panel-heading"><h3>Synergies · Sync Skills</h3></div>${f.syncSkills.map(s=>`<div class="ability-item"><div><strong>${esc(s.name)}</strong><p>${esc(s.text)}</p>${s.textNwus?`<p>PvP : ${esc(s.textNwus)}</p>`:''}</div></div>`).join('')}</section>`:''}
  ${f.awakening?`<section class="panel"><div class="panel-heading"><h3>Éveil ${f.stars}★ → ${f.awakening.to}★</h3></div><div class="panel-body help-copy">${f.awakening.materials.map(m=>`<div class="awakening-material">${materialGraphic(m)}<span>${esc(m.name)} ${m.stars?m.stars+'★':''} × <strong>${m.count}</strong></span></div>`).join('')}</div></section>`:''}
  <section class="panel"><div class="panel-heading"><h3>Obtention & disponibilité</h3></div><div class="panel-body help-copy">${n.obtain.map(o=>`${esc(o.type)} · <strong>${esc(o.name)}</strong>`).join('<br>')}<br>${n.obtain.some(o=>o.type==='gift')?'Cadeau confirmé sur le compte de référence · '+(n.id==='client-11016-might-guy-hot-blooded-youth'?(isPersonalAccount()?'réception et bonus à vérifier dans ta box':'Guy 6★, niveau 100 sans Limit Break · bonus à renseigner'):'forme reçue à renseigner'):`Référence communautaire : ${esc(n.serverReleased||availability(n))} ${n.upcoming?'(date indicative)':''}<br>${f.currentAvailabilityConfirmed?'Forme confirmée dans le jeu par tes captures ou ta confirmation':'Forme actuelle à confirmer'} · obtention actuelle en invocation / événement : à vérifier`}<br>Sortie originale : JP ${esc(f.released.japan||'—')} · Global ${esc(f.released.global||'—')}</div></section>
  ${f.notes.length?`<section class="skill-block"><div class="skill-kind">Notes de mécanique</div><p>${esc(f.notes.join('\n\n'))}</p></section>`:''}<p class="caption">Les totaux additionnent les statistiques de base, les pilules et les bonus fixes des capacités. Les effets conditionnels, synergies, terrain et soutien dépendent du combat et sont exclus. Les textes de techniques sont conservés en anglais. Les valeurs non décodées sont signalées dans leur fiche.</p><div class="source-links">${n.catalogueUrl?`<a href="${safeUrl(n.catalogueUrl)}" target="_blank" rel="noopener">Fiche GachaWiki ↗</a>`:''}${f.source.url?`<a href="${safeUrl(f.source.url)}" target="_blank" rel="noopener">Source originale · carte #${f.cardNo} ↗</a>`:`<span class="caption">Source : client NBRC3.00.032 · unité ${f.client.unitId}</span>`}${editable&&p.owned?'<button class="button compact soft" data-tab="progress">Renseigner ma progression →</button>':canPlanCharacter(n)?planToggleButton(n,p):''}${canPlanCharacter(n)&&!p.owned?'<button class="button compact soft" data-tab="resources">Voir les besoins prévisionnels →</button>':''}</div>`;
}
function progressInput(key,label,value,max,hint,min=0){return `<div><label for="progress-${key}">${label}</label><input type="number" id="progress-${key}" name="${key}" min="${min}" max="${max}" step="1" value="${value??''}" placeholder="Inconnu"><small>${hint}</small></div>`;}
function progressAbilityButtons(n,f,value){return f.abilities.map((a,i)=>`<button type="button" data-progress-ability="${i+1}" role="checkbox" aria-checked="${value!==null&&i<value}" aria-label="${esc(n.name+' — '+displayTitle(n))} · capacité ${i+1} : ${esc(a.name)}" title="${esc(a.name)} · ${value===null?'À préciser':i<value?'Débloquée':'À débloquer'}">${abilityGraphic(a,value!==null&&i<value)}</button>`).join('');}
function progressAbilities(n,f,value){return `<div class="progress-abilities-block"><span class="progress-field-label">Capacités débloquées</span><input type="hidden" id="progress-abilities" name="abilities" value="${value??''}"><div id="progress-ability-icons" class="ability-icons progress-ability-icons">${progressAbilityButtons(n,f,value)}</div><small id="progress-ability-count">${value??'?'} / ${f.abilities.length} débloquées</small><button type="button" class="field-shortcut" data-preset="abilities">Toutes débloquées</button></div>`;}
function refreshProgressAbilities(){const n=byId.get(ui.dialogId),f=n.forms.find(x=>x.client.unitId===Number($('#progress-unitId').value))||n.forms[0],input=$('#progress-abilities');if(!input)return;let value=numeric(input.value);if(value!==null&&value>f.abilities.length){value=f.abilities.length;input.value=value;}$('#progress-ability-icons').innerHTML=progressAbilityButtons(n,f,value);$('#progress-ability-count').textContent=`${value??'?'} / ${f.abilities.length} débloquées`;}
function renderProgress(n,p){
  if(!canEditCharacter(n))return renderFiche(n,p);
  const goal=planningCharacter(n);if(!goal){$('#dialog-body').innerHTML='<div class="notice">Cette version dépasse 6★ et reste indisponible pour la progression actuelle.</div>';return;}const forms=progressForms(n),f=forms.find(x=>x.client.unitId===p.unitId)||forms.find(x=>x.stars===p.stars)||forms[0],list=owned(),index=list.findIndex(x=>x.id===n.id);
  $('#dialog-body').innerHTML=`<div class="entry-progress"><label for="entry-character">Personnage ${index>=0?index+1:'—'} / ${list.length}</label><select id="entry-character" aria-label="Changer de personnage">${index<0?`<option value="${n.id}" selected>${esc(n.name+' · '+displayTitle(n))}</option>`:''}${list.map(x=>`<option value="${x.id}" ${x.id===n.id?'selected':''}>${esc(x.name+' · '+x.title)}</option>`).join('')}</select></div><h3>Ma progression</h3><p class="caption">Saisis le niveau affiché dans le jeu. Le calcul d’EXP part du début du niveau saisi ; tes stocks se renseignent séparément.</p>
  <form id="progress-form"><div class="entry-shortcuts"><span>Raccourcis</span><button type="button" data-preset="level">Niveau MAX</button><button type="button" data-preset="pills-hp-atk">Pilules PV / ATK MAX</button><button type="button" data-preset="pills">Toutes les pilules MAX</button><button type="button" data-preset="all">Personnage entièrement maxé</button></div><div class="progress-grid primary-progress"><div><label for="progress-unitId">Forme actuelle</label><select id="progress-unitId" name="unitId"><option value="">À renseigner</option>${forms.map(x=>`<option value="${x.client.unitId}" ${p.unitId===x.client.unitId||!p.unitId&&p.stars===x.stars?'selected':''}>${x.stars}★ · carte #${x.cardNo}${x.blazingAwakened?' · Blazing Awakening':''}</option>`).join('')}</select><small>${isPersonalAccount()?'Formes de ta box · le plan vise 6★ maximum':'Objectif actuel : '+goal.maxStars+'★ · 6★ maximum'}</small></div>${progressInput('level','Niveau actuel',p.level,f.client.finalCap,`Maximum ${f.client.finalCap} · 0 pour un nouveau personnage`,0)}</div>
  <div class="entry-field-heading"><h4>Bonus de pilules</h4><small>Bonus affichés sur la fiche du jeu, pas le nombre de pilules</small></div><div class="progress-grid pills-progress">${progressInput('hp','PV',p.hp,f.client.pillCaps.hp,`Maximum +${f.client.pillCaps.hp}`)}${progressInput('atk','Attaque',p.atk,f.client.pillCaps.atk,`Maximum +${f.client.pillCaps.atk}`)}${progressInput('speed','Vitesse',p.speed,f.client.pillCaps.speed,`Maximum +${f.client.pillCaps.speed}`)}</div>
  <div class="progress-grid">${progressAbilities(n,f,p.abilities)}<div>${progressInput('luck','Chance actuelle',p.luck,f.luck.max,`Maximum ${f.luck.max}`)}<button type="button" class="field-shortcut" data-preset="luck">Chance MAX</button></div></div>
  <div id="progress-preview">${ultimateNotice(n,p)}</div><p class="caption">Les raccourcis remplissent les champs. Clique sur Enregistrer pour appliquer ces valeurs. Le LB est déduit du niveau saisi.</p><div class="progress-actions"><label><input type="checkbox" name="owned" ${p.owned?'checked':''} ${!canEditCharacter(n)?'disabled':''}>Dans ma box</label><label><input type="checkbox" name="planned" ${p.planned?'checked':''} ${!canUseResourcePlan(n)?'disabled':''}>Mon plan</label><button class="button" type="submit">Enregistrer</button>${index>=0&&index<list.length-1?'<button class="button primary" type="submit" data-next="true">Enregistrer et suivant →</button>':''}</div><p id="progress-error" class="caption" role="alert"></p></form>`;
}
function syncProgressFields(){const n=byId.get(ui.dialogId),f=n.forms.find(x=>x.client.unitId===Number($('#progress-unitId').value))||n.forms[0];for(const [key,cap]of [['level',f.client.finalCap],['luck',f.luck.max],...['hp','atk','speed'].map(k=>[k,f.client.pillCaps[k]])]){const input=$(`#progress-${key}`);input.max=cap;input.nextElementSibling.textContent=key==='abilities'?`Sur ${cap}`:key==='level'?`Maximum de cette forme : ${cap}`:`Maximum ${['hp','atk','speed'].includes(key)?'+':''}${cap}`;}refreshProgressAbilities();return f;}
function refreshProgressPreview(){const form=$('#progress-form');if(!form)return;const n=byId.get(ui.dialogId),q={...state.characters[n.id]},f=n.forms.find(x=>x.client.unitId===Number($('#progress-unitId').value));q.unitId=f?.client.unitId??null;q.stars=f?.stars??null;q.owned=form.elements.owned.checked;for(const k of ['level','hp','atk','speed','abilities','luck'])q[k]=numeric($(`#progress-${k}`).value);$('#progress-preview').innerHTML=ultimateNotice(n,q);}
function applyProgressPreset(kind){const n=byId.get(ui.dialogId);if(kind==='all')$('#progress-unitId').value=progressForms(n).at(-1).client.unitId;else if(!$('#progress-unitId').value)$('#progress-unitId').value=displayForm(n,state.characters[n.id]).client.unitId;const f=syncProgressFields(),set=(k,v)=>$(`#progress-${k}`).value=v;if(['level','all'].includes(kind)){set('level',f.client.finalCap);}if(kind==='pills-hp-atk')for(const k of ['hp','atk'])set(k,f.client.pillCaps[k]);if(['pills','all'].includes(kind))for(const k of ['hp','atk','speed'])set(k,f.client.pillCaps[k]);if(['abilities','all'].includes(kind))set('abilities',f.abilities.length);if(['luck','all'].includes(kind))set('luck',f.luck.max);refreshProgressAbilities();refreshProgressPreview();$('#progress-error').textContent='Valeurs remplies · clique sur Enregistrer pour les conserver.';}

function trainingDetails(t,element){if(!t.stages.length)return'';const mix=t.ramen;return `<section class="panel"><div class="panel-heading"><h3>EXP & mélange de ramen</h3></div><div class="panel-body"><p><strong>${t.experienceNeeded===null?'Référence · ':''}${fmt(t.experienceNeeded??t.experienceUpperBound)} EXP nécessaires</strong></p><div class="ramen-mix-counts">${ramenMixCounts(mix?.counts??mix?.countsReference,element)}</div><p class="caption">${fmt(mix?.providedExperience??mix?.providedExperienceReference)} EXP fournies · surplus ${fmt(mix?.wastedExperience??mix?.wastedExperienceReference)}. Calcul depuis le début du niveau saisi ; ryō de nourrissage à part.</p><details><summary>Détail par forme et plafond</summary>${t.stages.map(x=>`<div class="ramen-chain-element"><strong>${x.stars}★ · niveau ${x.fromLevel} → ${x.toLevel}</strong><div class="ramen-mix-counts">${ramenMixCounts(x.counts,element)}</div><small>${x.known?'':'Référence · '}${fmt(x.experienceNeeded??x.experienceReference)} EXP nécessaires · ${fmt(x.providedExperience??x.providedExperienceReference)} fournies · surplus ${fmt(x.wastedExperience??x.wastedExperienceReference)}</small></div>`).join('')}</details></div></section>`;}
