function restore(text){
  let next,raw,photo;try{raw=JSON.parse(text);photo=raw?.format==='naruto-blazing-box';next=photo?importPhotoBox(raw,catalogue):validateBackup(raw,catalogue,profile);next.training.mixedRamen=true;}catch(error){
    importFeedback={error:true,message:(error.message||'JSON invalide.')+' Ta box actuelle est conservée.'};
    const status=$('#box-import-status');if(status){status.innerHTML=`<p>${esc(importFeedback.message)}</p>`;status.classList.add('error');status.setAttribute('role','alert');status.focus();}notify(importFeedback.message);return false;
  }
  state=next;const count=owned().length,unknown=accountStockKeys().filter(key=>stockFor(key,state.stocks)===null).length;
  importFeedback={message:photo?`${count} version${count===1?' observée importée':'s observées importées'} dans ${accountName()}. ${unknown} stock${unknown===1?' reste inconnu':'s restent inconnus'} et se renseigne${unknown===1?'':'nt'} dans Plan & stocks.`:`Sauvegarde restaurée pour ${accountName()}. Collection, progression et stocks conservés.`,notes:state.importNotes||[]};
  ui.scope='owned';ui=resetCollectionFilters(ui);resetPlanFilters();ui.resourceSearch='';if($('#character-dialog').open)$('#character-dialog').close();persist();renderPage();const status=$('#box-import-status');(status||$('#main')).focus();notify(photo?'Box importée. Vérifie les informations à compléter.':'Collection, progression et stocks restaurés.');return true;
}
function promptFeedback(message,error=false){const status=$('#copy-prompt-status');if(status){status.textContent=message;status.classList.toggle('error',error);status.setAttribute('role',error?'alert':'status');status.focus({preventScroll:true});}else notify(message);}
async function copyImportPrompt(button){
  button.disabled=true;try{
    if(!importPromptText){const response=await fetch('import-box-prompt.txt',{cache:'no-store'});if(!response.ok)throw Error('Le prompt ne peut pas être chargé. Réessaie ou utilise son lien de téléchargement.');importPromptText=(await response.text()).trim();if(!importPromptText)throw Error('Le prompt est vide. Utilise le lien de téléchargement ou réessaie.');}
    try{if(!navigator.clipboard?.writeText)throw Error();await navigator.clipboard.writeText(importPromptText);promptFeedback('Prompt copié. Ouvre ChatGPT, colle-le et joins tes captures.');}
    catch{const box=$('#import-prompt-fallback'),field=$('#import-prompt-text');if(!box||!field){notify('Le prompt est prêt dans le lien de téléchargement.');return;}box.hidden=false;field.value=importPromptText;promptFeedback('Copie automatique indisponible : le prompt est sélectionné ci-dessous. Copie-le puis colle-le dans ChatGPT.');field.focus();field.select();}
  }catch(error){promptFeedback(error.message||'Le prompt ne peut pas être chargé. Utilise son lien de téléchargement.',true);}finally{button.disabled=false;}
}
